  \foreach \a in {0,30,...,180}{\draw[ink] (0,0) -- (\a:0.409);}
  \fill[ink] (0,0) circle (1.2pt);
  \node[below] at (0,0) {$O$};
  \node[below] at (0.95,-0.02) {$1{,}6$ dm};
  \node[below] at (-0.95,-0.02) {$2{,}2$ dm};
\end{tikzpicture}
}
\par\vspace{2pt}{\sffamily\scriptsize\itshape\color{muted}Hình 7}
\end{minipage}

